    return (a + b + c + d) / 4.0f;
}

// Function to perform the Seidel relaxation
void kernel_seidel_2d(int tsteps, int n, DATA_TYPE *A, int *t) {
    // Initialize local loop variables
    int t, i, j;
    float t_step, x, y, x_val, y_val, x_avg, y_avg;

    // Set up the parallel region
    #pragma omp parallel for schedule(static) collapse(2)
