        // Distribute the work among the available threads
        #pragma omp master
        {
            // Initialize local variables
            t_step = t / tsteps;
            x = 0.5 * t_step;
            y = 0.5 * t_step;

            // Iterate over the matrix in parallel
            for (i = 1; i < n - 1; i++) {
                for (j = 1; j < n - 1; j++) {
                    // Calculate the average of the four neighboring values
                    x_val = compute_average(A[i - 1][j], A[i][j], A[i + 1][j], A[i][j + 1]);
                    y_val = compute_average(A[i][j - 1], A[i][j], A[i][j + 1], A[i + 1][j]);

                    // Update the element in the matrix
                    A[i][j] = (A[i][j] + x_val + y_val) / 2.0f;
                }
            }
        }
    }
}

