    double mean = mean_column(data, col_index);
    double sum_of_squares = 0.0;
    for (int i = 0; i < omp_get_num_threads(); ++i) {
        double diff = data[i * omp_get_num_threads() + col_index] - mean;
        sum_of_squares += diff * diff;
    }
    return sqrt(sum_of_squares / omp_get_num_threads());
}

